    /// <summary>Runs every lazy ensure the sweep specs can read (idempotent).</summary>
    internal static async Task EnsureAllAsync(
        System.Data.Common.DbConnection c, CancellationToken ct)
    {
        await ErpLazySchema.EnsureInventoryAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsureSuppliersAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsurePayrollAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsureProjectAccountingAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsurePmMastersAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsureBankReconAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsureAuditLogAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsureReturnAndVariantTablesAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsurePeriodCloseAsync(c, ct).ConfigureAwait(false);
        await ErpLazySchema.EnsureOrderPlanningAsync(c, ct).ConfigureAwait(false);
        await ErpPurchasingWorkspaceSpecs.EnsurePurchasingAsync(c, ct).ConfigureAwait(false);
        await ErpSalesOrderWriteService.EnsureSchemaAsync(c, ct).ConfigureAwait(false);
        await ErpSalesInvoiceWriteService.EnsureSchemaAsync(c, ct).ConfigureAwait(false);
        await ErpProductionWorkspaceSpecs.EnsureProductionAsync(c, ct).ConfigureAwait(false);
        await ErpBankingWorkspaceSpecs.EnsureBankingAsync(c, ct).ConfigureAwait(false);
        await ErpInventoryReservationWriteService.EnsureSchemaAsync(c, ct).ConfigureAwait(false);
    }
}
